        await rename(join(attemptDir, 'native'), delivery);
        await copyFile(join(attemptDir, 'engine.log'), join(delivery, 'engine.log'), constants.COPYFILE_EXCL);
        await chmod(join(delivery, 'engine.log'), 0o600);
