    need(Buffer.isBuffer(doc.bytes)||doc.bytes instanceof Uint8Array,'ZOTERO_DOCUMENT_BYTES_REQUIRED');
    const bytes=Buffer.from(doc.bytes);totalBytes+=bytes.length;
